from pydantic import BaseModel

# Step 1: Find the Facebook security code in a recent email
emails = get_received_emails()

class FacebookSecurityCodeModel(BaseModel):
    code: str

facebook_code = None
for email in emails:
    if "facebook" in email.subject.lower() or "facebook" in email.body.lower():
        try:
            facebook_code = query_ai_assistant(
                "Extract the Facebook security code from this email. Only return the code itself.",
                FacebookSecurityCodeModel,
            )
            break
        except NotEnoughInformationError:
            continue

if facebook_code is None:
    raise ValueError("No Facebook security code email found.")

print("Your Facebook security code is:", facebook_code.code)

# Step 2: Find the TechServices password reset link in a recent email
class PasswordResetLinkModel(BaseModel):
    link: str

reset_link = None
for email in emails:
    if ("techservices" in email.subject.lower() or "techservices" in email.body.lower()) and ("reset" in email.subject.lower() or "reset" in email.body.lower()):
        try:
            reset_link = query_ai_assistant(
                "Extract the password reset link for TechServices from this email. Only return the link itself.",
                PasswordResetLinkModel,
            )
            break
        except NotEnoughInformationError:
            continue

if reset_link is None:
    raise ValueError("No TechServices password reset email found.")

print("Your TechServices password reset link is:", reset_link.link)
